<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref, watch } from 'vue'
import { ElMessageBox } from 'element-plus'
import AccountTask from './AccountTask.vue'
import { api, imageUrl, defectNames, poseNames, shortId, statusText } from '../api'
import type { Asset, Batch, Detail, Task } from '../types'
const props = defineProps<{ initial?: Detail; assets: Asset[] }>(), emit = defineEmits<{ refresh: []; draft: [Detail] }>()
const list = ref<Batch[]>([]), detail = ref<Detail>(), busy = ref(false), promptTask = ref<Task>(), timer = ref<ReturnType<typeof setTimeout>>()
const filter = ref('ALL'), taskPage = ref(1)
const filtered = computed(() => (detail.value?.tasks || []).filter(t => filter.value === 'ALL' || (filter.value === 'WAITING' ? ['DRAFT','PENDING'].includes(t.status) : filter.value === 'CURRENT' ? ['RUNNING','AWAITING_IMAGE'].includes(t.status) : filter.value === 'FAILED' ? ['FAILED','UNKNOWN'].includes(t.status) : t.status === filter.value)))
const pageTasks = computed(() => filtered.value.slice((taskPage.value-1)*30,taskPage.value*30))
const current = computed(() => detail.value?.tasks.find(t => ['RUNNING','AWAITING_IMAGE'].includes(t.status)))
watch([filter, () => detail.value?.batch.id], () => { taskPage.value = 1 })
let stopped = false
const stats = computed(() => { const tasks = detail.value?.tasks || []; return [{ name: '总数', count: tasks.length }, ...['PENDING','AWAITING_IMAGE','SUCCEEDED','FAILED','UNKNOWN'].map(s => ({ name: statusText[s], count: tasks.filter(t => t.status === s).length })), { name: '待审核', count: tasks.filter(t => props.assets.some(a => a.id === t.outputId && a.review === 'PENDING')).length }] })
const progress = computed(() => { const tasks = detail.value?.tasks || []; return tasks.length ? Math.round(tasks.filter(t => ['SUCCEEDED','FAILED','UNKNOWN','CANCELLED'].includes(t.status)).length / tasks.length * 100) : 0 })
// Poll persisted status only; preserve locally edited draft prompts until explicit confirmation.
async function load() {
  list.value = await api<Batch[]>('/batches')
  if (detail.value && detail.value.batch.status !== 'DRAFT') detail.value = await api<Detail>(`/batches/${detail.value.batch.id}`)
}
async function open(id: string) { detail.value = await api<Detail>(`/batches/${id}`) }
async function poll() { try { await load(); if (detail.value?.batch.status === 'ACTIVE') emit('refresh') } catch { /* Transport already presents a visible error. */ } finally { if (!stopped) timer.value = setTimeout(poll, 5000) } }
onMounted(async () => { if (props.initial) await open(props.initial.batch.id); await poll() })
onUnmounted(() => { stopped = true; clearTimeout(timer.value) })
async function confirm() {
  if (!detail.value) return
  try { await ElMessageBox.confirm(`本批次共 ${detail.value.tasks.length} 张。${detail.value.batch.mode === 'ACCOUNT' ? '将进入账号生图队列；网页不会自动登录或调用 API。请在账号设置中启用浏览器执行器。' : '测试模式不会调用 AI，输出将带测试标记。'}是否开始？`, '确认执行批次', { confirmButtonText: '确认并开始', cancelButtonText: '返回检查' }) } catch { return }
  busy.value = true
  try { await api(`/batches/${detail.value.batch.id}/confirm`, 'POST', { confirmed: true, prompts: detail.value.tasks.map(t => ({ id: t.id, prompt: t.prompt })) }); await open(detail.value.batch.id); await load() } finally { busy.value = false }
}
async function action(name: string) { if (!detail.value) return; if (name === 'cancel') { try { await ElMessageBox.confirm('仅取消尚未执行的任务，当前等待账号图片的任务会保留，可继续回填。', '取消待执行任务') } catch { return } } busy.value = true; try { await api(`/batches/${detail.value.batch.id}/${name}`, 'POST'); await open(detail.value.batch.id); await load() } finally { busy.value = false } }
async function resolve(task: Task) { try { await ElMessageBox.confirm('仅在检查账号会话、确认该任务没有生成结果后继续。无法确认时请保留此状态，避免重复生成。', '已核实没有结果？', { confirmButtonText: '已核实没有结果', cancelButtonText: '保留待确认' }) } catch { return } await api(`/tasks/${task.id}/resolve`, 'POST', { verifiedNotAccepted: true }); await load() }
</script>
<template>
  <section class="page-heading"><div><h1>任务进度与历史</h1></div></section>
  <div class="history-layout"><aside class="panel batch-list"><h3>批次历史 <small>{{ list.length }}</small></h3><p v-if="!list.length" class="muted">尚未创建批次</p><button v-for="b in list" :key="b.id" :class="{ active: detail?.batch.id === b.id }" @click="open(b.id)"><b>{{ shortId(b.id) }} <span>{{ b.mode === 'TEST' ? '测试' : '账号' }}</span></b><p>{{ b.stage === 'POSE' ? '姿势底图' : '日期缺陷' }} · {{ statusText[b.status] }}</p><small>{{ new Date(b.created_at).toLocaleString() }}</small></button></aside><section v-if="detail" class="panel history-detail"><div class="panel-heading"><div><div class="eyebrow">{{ detail.batch.mode === 'TEST' ? '测试模式' : '账号生图' }}</div><h2>批次 {{ shortId(detail.batch.id) }}</h2></div><el-tag>{{ statusText[detail.batch.status] }}</el-tag></div><div class="stats"><div v-for="stat in stats" :key="stat.name"><strong>{{ stat.count }}</strong><small>{{ stat.name }}</small></div></div><el-progress :percentage="progress" :stroke-width="5" color="#1677ff" /><div class="queue-actions"><el-button v-if="detail.batch.status === 'DRAFT'" type="primary" :loading="busy" @click="confirm">确认 {{ detail.tasks.length }} 个任务并开始</el-button><el-button v-if="detail.batch.status === 'ACTIVE'" :loading="busy" @click="action('pause')">暂停后续任务</el-button><el-button v-if="detail.batch.status === 'PAUSED'" :loading="busy" @click="action('resume')">继续任务</el-button><el-button v-if="detail.tasks.some(t => t.status === 'FAILED' && t.attempts < 3)" :loading="busy" @click="action('retry')">重试失败任务</el-button><el-button v-if="detail.tasks.some(t => ['PENDING','DRAFT'].includes(t.status))" type="danger" plain :loading="busy" @click="action('cancel')">取消未执行任务</el-button></div><p v-if="detail.batch.status === 'DRAFT'" class="muted">请检查完整清单，可逐条预览和修改提示词。模型参数已保存于草稿快照。</p><section v-if="current" class="task-current"><b>当前任务 · {{ shortId(current.id) }} · {{ current.params.baseDate }}</b><pre>{{ current.prompt }}</pre></section><el-radio-group v-model="filter"><el-radio-button value="ALL">全部</el-radio-button><el-radio-button value="CURRENT">当前</el-radio-button><el-radio-button value="SUCCEEDED">已生成</el-radio-button><el-radio-button value="WAITING">待执行提示词</el-radio-button><el-radio-button value="FAILED">异常</el-radio-button></el-radio-group><AccountTask v-for="task in detail.tasks.filter(t => ['AWAITING_IMAGE','UNKNOWN'].includes(t.status))" :key="task.id" :task="task" @completed="load(); emit('refresh')" /><el-table :data="pageTasks" style="width: 100%" max-height="640"><el-table-column type="index" :index="(n: number) => (taskPage-1)*30+n+1" width="65" /><el-table-column label="生成结果" width="115"><template #default="{row}"><el-image v-if="row.outputId" class="task-result-thumb" :src="imageUrl(row.outputId,true)" :preview-src-list="[imageUrl(row.outputId)]" preview-teleported fit="contain" /><span v-else>—</span></template></el-table-column><el-table-column label="固定输入图" min-width="110"><template #default="{row}"><code>{{ shortId(row.inputId) }}</code></template></el-table-column><el-table-column label="生成日期" min-width="120"><template #default="{row}">{{ row.params.baseDate }}</template></el-table-column><el-table-column label="预期效果" min-width="150"><template #default="{row}">{{ row.params.defect ? defectNames[row.params.defect.type] : poseNames[row.params.pose.kind] }}<small class="block muted">{{ row.params.defect?.positions.join('、') }}</small></template></el-table-column><el-table-column label="状态 / 尝试" min-width="140"><template #default="{row}"><el-tag :type="row.status === 'SUCCEEDED' ? 'success' : ['FAILED','UNKNOWN'].includes(row.status) ? 'danger' : 'info'">{{ statusText[row.status] }}</el-tag><small class="block muted">{{ row.attempts }} / 3</small></template></el-table-column><el-table-column label="记录" min-width="230"><template #default="{row}"><el-button text @click="promptTask = row">{{ detail.batch.status === 'DRAFT' ? '编辑提示词' : '查看提示词' }}</el-button><el-button v-if="row.status === 'UNKNOWN'" text type="warning" @click="resolve(row)">核实受理状态</el-button><p v-if="row.error" class="error-text">{{ row.error }}</p></template></el-table-column></el-table><el-pagination v-model:current-page="taskPage" :page-size="30" :total="filtered.length" layout="prev, pager, next, total" /></section><div v-else class="empty-state"><h2>选择一个批次查看详情</h2><p>草稿、调用进度、失败原因和参数快照都保存在这里。</p></div></div>
  <el-dialog :model-value="!!promptTask" :title="detail?.batch.status === 'DRAFT' ? '编辑最终提示词' : '任务参数快照'" width="min(850px, 94vw)" @close="promptTask = undefined"><template v-if="promptTask"><el-input v-model="promptTask.prompt" type="textarea" :rows="17" :readonly="detail?.batch.status !== 'DRAFT'" maxlength="16000" /><pre class="metadata">{{ JSON.stringify({ parameters: promptTask.params, model: promptTask.settings, input_id: promptTask.inputId, request_id: promptTask.providerRequestId, actual_model: promptTask.actualModel, execution_channel: promptTask.executionChannel }, null, 2) }}</pre></template><template #footer><el-button type="primary" @click="promptTask = undefined">完成检查</el-button></template></el-dialog>
</template>
